  "processingTime" = EXCLUDED."processingTime", "validity" = EXCLUDED."validity", "whereToApply" = EXCLUDED."whereToApply",
  "applyUrl" = EXCLUDED."applyUrl", "appointmentUrl" = EXCLUDED."appointmentUrl", "visaCenter" = EXCLUDED."visaCenter",
